// Writes page-number-parts.docx from hand-written WordprocessingML (see README.md).
import { zipSync, strToU8 } from 'fflate';
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const NS = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"';
const head = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';
const complex = (code, cached) => `<w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText xml:space="preserve"> ${code} </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:rPr><w:noProof/></w:rPr><w:t>${cached}</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r>`;
const part = (gallery, id, inner, end = '') => `<w:sdt><w:sdtPr><w:id w:val="${id}"/><w:docPartObj><w:docPartGallery w:val="${gallery}"/><w:docPartUnique/></w:docPartObj></w:sdtPr>${end}<w:sdtContent>${inner}</w:sdtContent></w:sdt>`;
const header = `<w:hdr ${NS}>${part('Page Numbers (Top of Page)', '-1318548329', `<w:p><w:pPr><w:pStyle w:val="Header"/><w:jc w:val="right"/></w:pPr>${complex('PAGE   \\* MERGEFORMAT', '1')}</w:p>`)}<w:p><w:pPr><w:pStyle w:val="Header"/></w:pPr></w:p></w:hdr>`;
const footer = `<w:ftr ${NS}>${part('Page Numbers (Bottom of Page)', '-2034520717', `<w:p><w:pPr><w:pStyle w:val="Footer"/><w:jc w:val="center"/></w:pPr><w:fldSimple w:instr=" PAGE   \\* MERGEFORMAT "><w:r><w:rPr><w:noProof/></w:rPr><w:t>1</w:t></w:r></w:fldSimple></w:p>`, '<w:sdtEndPr><w:rPr><w:noProof/></w:rPr></w:sdtEndPr>')}<w:p><w:pPr><w:pStyle w:val="Footer"/></w:pPr></w:p></w:ftr>`;
const pageOf = `<w:p><w:pPr><w:pStyle w:val="Footer"/><w:jc w:val="center"/></w:pPr><w:r><w:t xml:space="preserve">Page </w:t></w:r>${complex('PAGE', '1')}<w:r><w:t xml:space="preserve"> of </w:t></w:r>${complex('NUMPAGES', '1')}</w:p>`;
const firstFooter = `<w:ftr ${NS}>${part('Page Numbers (Bottom of Page)', '98404467', part('Page Numbers (Top of Page)', '1728636285', pageOf))}<w:p><w:pPr><w:pStyle w:val="Footer"/></w:pPr></w:p></w:ftr>`;
const body = `<w:document ${NS}><w:body>${Array.from({ length: 3 }, (_, i) => `<w:p>${i ? '<w:r><w:br w:type="page"/></w:r>' : ''}<w:r><w:t>Body page ${i + 1}</w:t></w:r></w:p>`).join('')}<w:sectPr><w:headerReference w:type="default" r:id="rIdH1"/><w:footerReference w:type="default" r:id="rIdF1"/><w:footerReference w:type="first" r:id="rIdF2"/><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440" w:header="720" w:footer="720" w:gutter="0"/><w:titlePg/></w:sectPr></w:body></w:document>`;
const styles = `<w:styles ${NS}><w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/></w:style><w:style w:type="paragraph" w:styleId="Header"><w:name w:val="header"/><w:basedOn w:val="Normal"/></w:style><w:style w:type="paragraph" w:styleId="Footer"><w:name w:val="footer"/><w:basedOn w:val="Normal"/></w:style></w:styles>`;
const type = name => `application/vnd.openxmlformats-officedocument.wordprocessingml.${name}+xml`;
const files = {
  '[Content_Types].xml': `<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="${type('document.main')}"/><Override PartName="/word/styles.xml" ContentType="${type('styles')}"/><Override PartName="/word/header1.xml" ContentType="${type('header')}"/><Override PartName="/word/footer1.xml" ContentType="${type('footer')}"/><Override PartName="/word/footer2.xml" ContentType="${type('footer')}"/></Types>`,
  '_rels/.rels': '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>',
  'word/_rels/document.xml.rels': '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rIdS" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/><Relationship Id="rIdH1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/header" Target="header1.xml"/><Relationship Id="rIdF1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" Target="footer1.xml"/><Relationship Id="rIdF2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" Target="footer2.xml"/></Relationships>',
  'word/document.xml': body, 'word/styles.xml': styles, 'word/header1.xml': header, 'word/footer1.xml': footer, 'word/footer2.xml': firstFooter,
};
const out = fileURLToPath(new URL('../../../public/fixtures/page-number-parts.docx', import.meta.url));
writeFileSync(out, zipSync(Object.fromEntries(Object.entries(files).map(([name, text]) => [name, strToU8(head + text)])), { mtime: new Date('2026-10-27T00:00:00Z') }));
